// PO_LINE_IMPORT - Guard: the Excel rows as the PO form's upload parsed them, each checked on its own (headers matched
// without case, spaces or punctuation), and the distinct item codes for the item read
const IMPORT_MAX_ROWS = 2500;
const ERRORS_SHOWN = 30;
const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
const digits = (v) => /^[0-9]{1,20}$/.test(s(v));
const normKey = (k) => String(k || "").toLowerCase().replace(/[^a-z0-9]/g, "");
const HEADERS = {
  code: ["itemcode", "code", "materialcode", "item"],
  qty: ["quantity", "qty"],
  uom: ["uom", "unit", "unitofmeasure", "unitofmeasurement", "quantityuom"],
  price: ["unitprice", "price"],
  discount: ["discount"],
  discountType: ["discounttype", "discountuom"],
  desc: ["description", "itemdescription"],
  remark1: ["remark1", "remark", "remarks", "lineremark1"],
  remark2: ["remark2", "lineremark2"],
  date: ["requireddeliverydate", "deliverydate", "expecteddeliverydate", "requireddate"],
};
const FIELD_OF = {};
for (const f of Object.keys(HEADERS)) for (const h of HEADERS[f]) FIELD_OF[h] = f;
const TEMPLATE = "Item Code, Quantity, UOM, Unit Price, Discount, Discount Type, Description, Remark 1, Remark 2, Required Delivery Date";
// a number as Excel or a person writes it: 1,250.5 -> 1250.5; blank -> null; anything else -> NaN
const numOf = (v) => {
  if (typeof v === "number") return isFinite(v) ? v : NaN;
  const t = s(v).replace(/,/g, "");
  if (t === "") return null;
  return /^[+-]?(\d+(\.\d*)?|\.\d+)$/.test(t) ? Number(t) : NaN;
};
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12 };
// a calendar date -> "YYYY-MM-DD"; blank -> ""; not a date -> null. Excel day numbers, ISO, day-month-year with - / or .,
// "1 Jan 2026" and "Jan 1, 2026"
const dateOf = (v) => {
  const p2 = (n) => (n < 10 ? "0" : "") + n;
  const ymd = (y, m, d) => {
    if (!(y >= 1900 && y <= 2999 && m >= 1 && m <= 12 && d >= 1)) return null;
    const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
    return d <= last ? y + "-" + p2(m) + "-" + p2(d) : null;
  };
  if (typeof v === "number") {
    if (!(v >= 1 && v < 2958466)) return null;
    const t = new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 86400000);
    return ymd(t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate());
  }
  const t = s(v);
  if (t === "") return "";
  let m = t.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?:[ T].*)?$/);
  if (m) return ymd(+m[1], +m[2], +m[3]);
  m = t.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/);
  if (m) return ymd(+m[3], +m[2], +m[1]);
  m = t.match(/^(\d{1,2})[\s-]+([A-Za-z]{3,9})[\s,-]+(\d{4})$/);
  if (m && MONTHS[m[2].slice(0, 4).toLowerCase()] !== undefined) return ymd(+m[3], MONTHS[m[2].slice(0, 4).toLowerCase()], +m[1]);
  if (m && MONTHS[m[2].slice(0, 3).toLowerCase()] !== undefined) return ymd(+m[3], MONTHS[m[2].slice(0, 3).toLowerCase()], +m[1]);
  m = t.match(/^([A-Za-z]{3,9})\s+(\d{1,2}),?\s+(\d{4})$/);
  if (m && MONTHS[m[1].slice(0, 3).toLowerCase()] !== undefined) return ymd(+m[3], MONTHS[m[1].slice(0, 3).toLowerCase()], +m[2]);
  return null;
};
const sqlText = (v) => String(v).replace(/\\/g, "\\\\").replace(/'/g, "''");

const importGuard = function importGuard(input) {
  const base = { route: "STOP", code: "400", message: "", errors: [], rows: [], codesSql: "[]", count: 0, tenantId: "", organizationId: "", supplierId: "", plantId: "" };
  const stop = (message, errors) => Object.assign(base, { message: message, errors: errors || [] });
  if (!digits(input.tenantId)) return stop("No session tenant.");
  if (!digits(input.organizationId)) return stop("The organization of this purchase order is not set.");
  if (s(input.supplierId) !== "" && !digits(input.supplierId)) return stop("The supplier of this purchase order is not valid.");
  if (s(input.plantId) !== "" && !digits(input.plantId)) return stop("The plant of this purchase order is not valid.");
  let raw = input.rows;
  if (typeof raw === "string") {
    try {
      raw = JSON.parse(raw);
    } catch (e) {
      return stop("The uploaded file could not be read.");
    }
  }
  if (!Array.isArray(raw)) return stop("The uploaded file could not be read.");
  const out = [];
  const errors = [];
  const unknownHeaders = {};
  let sawCode = false;
  raw.forEach((r, i) => {
    if (!r || typeof r !== "object") return;
    const n = i + 2; // row 1 is the header row
    const v = {};
    for (const k of Object.keys(r)) {
      const f = FIELD_OF[normKey(k)];
      if (f) {
        if (f === "code") sawCode = true;
        if (v[f] === undefined || s(v[f]) === "") v[f] = r[k];
      } else if (s(r[k]) !== "") unknownHeaders[k] = true;
    }
    if (Object.keys(v).every((f) => s(v[f]) === "")) return; // a blank row
    const err = (msg) => errors.push({ row: n, message: msg });
    const code = s(v.code);
    if (!code) return err("Item Code is empty");
    if (code.length > 255) return err("Item Code is longer than 255 characters");
    const qty = numOf(v.qty);
    if (qty === null) return err("Quantity is empty");
    if (!(qty > 0)) return err("Quantity must be a number above 0 (" + s(v.qty) + ")");
    const price = numOf(v.price);
    if (price !== null && !(price >= 0)) return err("Unit Price must be a number, 0 or above (" + s(v.price) + ")");
    const discount = numOf(v.discount);
    if (discount !== null && !(discount >= 0)) return err("Discount must be a number, 0 or above (" + s(v.discount) + ")");
    let discountType = "";
    const dt = normKey(v.discountType);
    if (s(v.discountType)) {
      if (s(v.discountType) === "%" || dt === "percent" || dt === "percentage" || dt === "pct") discountType = "%";
      else if (dt === "amount" || dt === "amt" || dt === "value") discountType = "Amount";
      else return err("Discount Type must be % or Amount (" + s(v.discountType) + ")");
    }
    if (discountType === "%" && discount !== null && discount > 100) return err("Discount above 100%");
    const date = dateOf(v.date);
    if (date === null) return err("Required Delivery Date is not a date (" + s(v.date) + ")");
    out.push({ n: n, code: code, qty: qty, uom: s(v.uom), price: price, discount: discount, discountType: discountType, desc: s(v.desc), remark1: s(v.remark1),
      remark2: s(v.remark2), date: date });
  });
  if (!sawCode) return stop("The file has no Item Code column. The template's columns are: " + TEMPLATE + ".");
  if (out.length + errors.length === 0) return stop("The file has no lines.");
  if (out.length + errors.length > IMPORT_MAX_ROWS) return stop("The file has " + (out.length + errors.length) + " lines. At most " + IMPORT_MAX_ROWS + " lines can be imported at once.");
  if (errors.length) return stop(errors.length + " line(s) cannot be imported - nothing was added.", errors);
  const codes = [...new Set(out.map((r) => r.code))];
  const parts = [];
  for (let i = 0; i < codes.length; i += 50) parts.push(codes.slice(i, i + 50).map((c) => JSON.stringify({ c: c })).join(","));
  return Object.assign(base, { route: "GO", code: "200", message: Object.keys(unknownHeaders).length ? "Columns not imported: " + Object.keys(unknownHeaders).join(", ") : "",
    rows: out, codesSql: sqlText("[" + parts.join(",\n") + "]"), count: out.length, tenantId: s(input.tenantId), organizationId: s(input.organizationId),
    supplierId: s(input.supplierId), plantId: s(input.plantId) });
};
const res = importGuard({ rows: [{{workflowparams:rows}}][0], tenantId: [{{system:tenantId}}][0], organizationId: [{{workflowparams:organization_id}}][0],
  supplierId: [{{workflowparams:supplier_id}}][0], plantId: [{{workflowparams:plant_id}}][0] });
res.errorsShown = res.errors.slice(0, ERRORS_SHOWN);
res.errorsJson = JSON.stringify(res.errorsShown);
res.errorCount = String(res.errors.length);
console.log("import guard", JSON.stringify({ route: res.route, count: res.count, errors: res.errors.length, message: res.message }));
return res;

// PO_LINE_IMPORT - Resolve: each row's item (its code, as the database compares codes) and UOM (one of the item's own,
// by name; blank = the default purchase UOM, as Batch Add takes it), every problem listed; the lines as Batch Add starts
// them (onConfirm_batchAddItem) and what GET_ITEM_UNIT_PRICE_BULK is asked for them
const parseJ = (t) => {
  try {
    return JSON.parse(String(t).replace(/"(?:[^"\\]|\\.)*"|-?\d{16,}(?![.\deE])/g, (m) => (m[0] === '"' ? m : '"' + m + '"')));
  } catch (e) {
    return null;
  }
};
const importResolve = function importResolve(guard, itemRows) {
  const s = (v) => (v === undefined || v === null ? "" : String(v)).trim();
  const base = { route: "STOP", code: "400", message: "", errors: [], errorsShown: [], lines: [], itemData: [], altUomJson: "{}", count: 0 };
  const key = (c) => s(c).toLowerCase();
  // what the file should say instead: the item's base UOM, then its other units
  const uomHint = (item, conv) => {
    const baseRow = conv.find((c) => s(c.alt_uom_id) === s(item.based_uom));
    const baseName = s(item.based_uom_name) || s(baseRow && baseRow.uom_name);
    const others = [...new Set(conv.map((c) => s(c.uom_name)).filter((n) => n && key(n) !== key(baseName)))];
    if (baseName) return ". Use its base UOM " + baseName + (others.length ? " (or " + others.join(", ") + ")" : "");
    return others.length ? ". Its units: " + others.join(", ") : "";
  };
  const byCode = {};
  for (const r of Array.isArray(itemRows) ? itemRows : itemRows ? [itemRows] : []) {
    const o = r && (typeof r.j === "string" ? parseJ(r.j) : r.j || r);
    if (!o || !s(o.id)) continue;
    (byCode[key(o.material_code)] = byCode[key(o.material_code)] || []).push(o);
  }
  const errors = [];
  const lines = [];
  // alt_uom once per item (the form puts it on each of the item's lines): the answer stays small when items repeat
  const altUom = {};
  for (const row of guard.rows || []) {
    const err = (msg) => errors.push({ row: row.n, message: msg });
    let found = byCode[key(row.code)] || [];
    if (found.length > 1) found = found.filter((o) => s(o.material_code) === row.code).length === 1 ? found.filter((o) => s(o.material_code) === row.code) : found;
    if (found.length === 0) {
      err("Item Code " + row.code + " was not found");
      continue;
    }
    if (found.length > 1) {
      err("Item Code " + row.code + " matches " + found.length + " items");
      continue;
    }
    const item = found[0];
    if (String(item.is_active) === "0") {
      err("Item " + row.code + " is inactive");
      continue;
    }
    const conv = Array.isArray(item.conv) ? item.conv : [];
    let uom = null;
    if (row.uom) {
      const named = conv.filter((c) => key(c.uom_name) === key(row.uom));
      if (named.length !== 1) {
        err(named.length ? "UOM " + row.uom + " matches " + named.length + " units of item " + row.code : "UOM " + row.uom + " is not a unit of item " + row.code + uomHint(item, conv));
        continue;
      }
      uom = named[0];
    } else {
      uom = conv.find((c) => String(c.purchase_default_uom) === "1") || conv.find((c) => s(c.alt_uom_id) === s(item.based_uom)) || null;
      if (!uom) {
        err("Item " + row.code + " has no purchase UOM: give the UOM");
        continue;
      }
    }
    const binds = Array.isArray(item.binds) ? item.binds : [];
    const bound = binds.find((b) => s(b.supplier_id) === s(guard.supplierId) && s(b.item_description));
    if (altUom[s(item.id)] === undefined) altUom[s(item.id)] = JSON.stringify(conv.map((c) => {
      const o = Object.assign({}, c);
      delete o.uom_name;
      return o;
    }));
    // onConfirm_batchAddItem's poItem, from the chosen UOM's row (blank UOM: the default purchase row it reads)
    lines.push({
      row: row,
      line: {
        item_id: s(item.id),
        item_name: item.material_name === undefined ? null : item.material_name,
        item_desc: s(bound && bound.item_description) || item.material_desc || "",
        unit_price: uom.purchase_unit_price || 0,
        item_category_id: item.item_category === undefined ? null : item.item_category,
        tax_preference: s(uom.mat_purchase_tax_id) || null,
        tax_percent: uom.purchase_tax_percent || null,
        quantity_uom: s(uom.alt_uom_id) || null,
        further_description: item.further_description === undefined ? null : item.further_description,
        min_quantity: uom.min_purchase_qty || 0,
        max_quantity: uom.max_purchase_qty || 0,
      },
      headerTax: s(item.mat_purchase_tax_id) ? 1 : 0,
    });
  }
  if (errors.length) return Object.assign(base, { message: errors.length + " line(s) cannot be imported - nothing was added.", errors: errors, errorsShown: errors.slice(0, 30) });
  // what Batch Add asks GET_ITEM_UNIT_PRICE_BULK, plus the quantity the file gives (price tags apply by quantity)
  const itemData = lines.map((l, i) => ({ item_id: l.line.item_id, unit_price: l.line.unit_price, line_index: i, uom_id: l.line.quantity_uom, tax_rate: l.line.tax_preference || null,
    tax_percent: l.line.tax_percent || null, quantity: l.row.qty }));
  return Object.assign(base, { route: "GO", code: "200", lines: lines, itemData: itemData, altUomJson: JSON.stringify(altUom), count: lines.length });
};
const res = importResolve([{{node:code_node_PIguard.data}}][0], [{{node:sql_node_PIitems.data}}][0]);
res.errorsJson = JSON.stringify(res.errorsShown);
res.errorCount = String(res.errors.length);
console.log("import resolve", JSON.stringify({ route: res.route, lines: res.count, errors: res.errors.length }));
return res;

// PO_LINE_IMPORT - Rows: each line as Batch Add leaves it after GET_ITEM_UNIT_PRICE_BULK answers (onConfirm_batchAddItem's
// update), then what the file gives on top (its quantity always; price, discount, description, remarks, date when filled)
const importRows = function importRows(resolved, priceData) {
  const lines = resolved.lines || [];
  const priced = {};
  for (const p of Array.isArray(priceData) ? priceData : priceData ? [priceData] : []) if (p && p.line_index !== undefined) priced[String(p.line_index)] = p;
  const rows = [];
  const taxOpen = [];
  lines.forEach((l, i) => {
    const row = Object.assign({}, l.line);
    const p = priced[String(i)];
    if (p) {
      Object.assign(row, { unit_price: p.unit_price, quantity_uom: p.uom_id, tax_preference: p.tax_rate, tax_percent: p.tax_percent, from_historical: p.from_historical,
        max_price: p.max_price, min_price: p.min_price, quantity: p.quantity, min_qty: p.min_qty, max_qty: p.max_qty, discount: p.discount, discount_uom: p.discount_uom });
    }
    const f = l.row;
    row.quantity = f.qty;
    if (f.price !== null && f.price !== undefined) row.unit_price = f.price;
    if (f.discount !== null && f.discount !== undefined) row.discount = f.discount;
    if (f.discountType) row.discount_uom = f.discountType;
    if (f.desc) row.item_desc = f.desc;
    if (f.remark1) row.line_remark_1 = f.remark1;
    if (f.remark2) row.line_remark_2 = f.remark2;
    if (f.date) row.po_expected_date = f.date;
    for (const k of Object.keys(row)) if (row[k] === undefined) delete row[k];
    // Batch Add keeps Tax Rate open on lines of items with a purchase tax of their own and no tax code
    if (l.headerTax === 1 && !row.tax_preference) taxOpen.push(i);
    rows.push(row);
  });
  return { route: "GO", code: "200", rowsJson: JSON.stringify(rows), taxOpenJson: JSON.stringify(taxOpen), count: String(rows.length) };
};
const res = importRows([{{node:code_node_PIresolve.data}}][0], [{{node:workflow_node_PIprice.data.data}}][0]);
console.log("import rows", JSON.stringify({ count: res.count, taxOpen: JSON.parse(res.taxOpenJson).length }));
return res;
